CREATE PROCEDURE [EXP_WarehouseMobileExample] (   
    @SESSIONVALUE xml,   
    @URL nvarchar(max),   
    @CUSTOM nvarchar(max),   
    @RETURNVALUE nvarchar(max) output   
)   
AS    
    SET NOCOUNT ON;    
  declare @customIndex numeric(9);
  declare @itemcolor nvarchar(25);

     Declare @id numeric(9)    
     SELECT @id = insNum   
     FROM OPENJSON(@CUSTOM)       
       WITH (   
       insNum numeric(9) '$.WorkExecutionChildEntities[0].InternalInstructionNum'   
       )
       SELECT @itemcolor =item_COLOR  from ITEM i Inner join work_instruction w on w.item = i.item
       and(( i.company = w.company) or i.company is null and w.company is null
       )
     where w.internal_instruction_num =@id
     set @RETURNVALUE ='{"ItemColor":'''+@itemcolor+'''}';

